DO $$
BEGIN
    IF to_regclass('recruitment.interviews') IS NOT NULL AND to_regclass('recruitment.job_applications') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('recruitment.interviews') AND c.contype = 'f' AND a.attname = 'application_id'
    ) THEN
        ALTER TABLE recruitment.interviews ADD CONSTRAINT fk_interviews_application_id FOREIGN KEY (application_id) REFERENCES recruitment.job_applications (id) NOT VALID;
        BEGIN
            ALTER TABLE recruitment.interviews VALIDATE CONSTRAINT fk_interviews_application_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_interviews_application_id left NOT VALID: stored rows of recruitment.interviews reference missing rows';
        END;
    END IF;
END $$;

